/**
 *
 * DataTableTFootCell is a component that displays a tfoot cell inside a DataTable.
 *
 * [Live Demo](https://www.primereact.org/datatable/)
 *
 * @module DataTableTFootCell
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataTableRootInstance } from './DataTableRoot.types';
/**
 * Defines passthrough(pt) options type in DataTableTFootCell component.
 */
export type DataTableTFootCellPassThroughType<E> = PassThroughType<DataTableTFootCellInstance, E>;
/**
 * Defines passthrough(pt) options of DataTableTFootCell component.
 */
export interface DataTableTFootCellPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataTableTFootCellPassThroughType<React.HTMLAttributes<HTMLTableCellElement>>;
}
/**
 * Defines valid properties in DataTableTFootCell component.
 */
export interface DataTableTFootCellProps extends BaseComponentProps<DataTableTFootCellInstance, unknown, DataTableTFootCellPassThrough, 'td'> {
    /**
     * Number of columns a footer cell should span.
     * @default undefined
     */
    colSpan?: number | undefined;
}
/**
 * Defines valid state in DataTableTFootCell component.
 */
export interface DataTableTFootCellState {
}
/**
 * Defines the methods and properties exposed by DataTableTFootCell component.
 */
export interface DataTableTFootCellExposes {
    /**
     * The DataTable component instance.
     */
    datatable: DataTableRootInstance | undefined | null;
}
/**
 * Instance of DataTableTFootCell component.
 */
export type DataTableTFootCellInstance = ComponentInstance<DataTableTFootCellProps, DataTableTFootCellState, DataTableTFootCellExposes>;
